<?php
namespace Modules\Analytics\Controllers\Web;
use Core\http\ResponseFactory;use Modules\Analytics\Services\AdminMediaService;use RuntimeException;
class AdminMediaController{public function __construct(private AdminMediaService$s){}public function index(){return$this->run(fn()=>['success'=>true,'data'=>$this->s->index($_GET)]);}public function upload(){return$this->run(function(){$id=$this->s->upload((int)auth()->id(),$_FILES['file']??[],$_POST);return['success'=>true,'data'=>['id'=>$id]];});}public function update(int$id){return$this->run(function()use($id){$this->s->update((int)auth()->id(),$id,$this->payload());return['success'=>true];});}public function delete(int$id){return$this->run(function()use($id){$this->s->delete((int)auth()->id(),$id);return['success'=>true];});}private function payload():array{$raw=base64_decode(strtr((string)request()->input('payload_b64',''),'-_','+/'),true);$d=$raw===false?null:json_decode($raw,true);if(!is_array($d))throw new RuntimeException('اطلاعات رسانه معتبر نیست.');return$d;}private function run(callable$c){try{return ResponseFactory::json($c());}catch(\Throwable$e){return ResponseFactory::json(['success'=>false,'message'=>$e->getMessage()],422);}}}
